class Solution {
public:
    int numRabbits(vector<int>& answers) {
        unordered_map<int, int> count;
        for (int x : answers) ++count[x];
        int total = 0;
        for (const auto& p : count) {
            int group = p.first + 1;
            total += ((p.second + group - 1) / group) * group;
        }
        return total;
    }
};
